        status = 'failed',
        error_code = v_error_code,
        updated_at = now(),
        completed_at = NULL
      WHERE cwe.svix_id = v_svix_id;

      RETURN jsonb_build_object(
        'ok', false,
        'status', 'failed',
        'error_code', v_error_code,
        'svix_id', v_svix_id
      );
  END;
END;
$$"

